class _Path0Painter extends CustomPainter {
  const _Path0Painter();

  @override
  void paint(Canvas canvas, Size size) {
    final path = Path();
    path.moveTo(0, 0);
    path.lineTo(8, 0);
    path.lineTo(4, 5);
    path.lineTo(0, 0);
    path.close();
  }

  @override
  bool shouldRepaint(_Path0Painter oldDelegate) => false;
}

class _Path1Painter extends CustomPainter {
  const _Path1Painter();

  @override
  void paint(Canvas canvas, Size size) {
    final path = Path();
    path.moveTo(120, 0);
    path.lineTo(120, 40);
    path.lineTo(0, 40);
    path.lineTo(120, 0);
    path.close();
  }

  @override
  bool shouldRepaint(_Path1Painter oldDelegate) => false;
}

class _Path2Painter extends CustomPainter {
  const _Path2Painter();

  @override
  void paint(Canvas canvas, Size size) {
    final path = Path();
    path.moveTo(0, 0);
    path.lineTo(186, 0);
    path.lineTo(186, 206);
    path.lineTo(0, 206);
    path.lineTo(0, 0);
    path.close();
    canvas.drawPath(path, Paint()..color = Color(0xFFFFDF25));
  }

  @override
  bool shouldRepaint(_Path2Painter oldDelegate) => false;
}

class _Path3Painter extends CustomPainter {
  const _Path3Painter();

  @override
  void paint(Canvas canvas, Size size) {
    final path = Path();
    path.moveTo(0, 0);
    path.lineTo(200, 0);
    path.lineTo(200, 30);
    path.lineTo(0, 30);
    path.lineTo(0, 0);
    path.close();
    canvas.drawPath(path, Paint()..color = Color(0x1AFE4066));
    canvas.drawPath(
      path,
      Paint()
        ..color = Color(0x99FE4066)
        ..style = PaintingStyle.stroke
        ..strokeWidth = 1,
    );
  }

  @override
  bool shouldRepaint(_Path3Painter oldDelegate) => false;
}

class _Path4Painter extends CustomPainter {
  const _Path4Painter();

  @override
  void paint(Canvas canvas, Size size) {
    final path = Path();
    path.moveTo(0, 0);
    path.lineTo(94, 0);
    path.lineTo(94, 30);
    path.lineTo(0, 30);
    path.lineTo(0, 0);
    path.close();
    canvas.drawPath(path, Paint()..color = Color(0x1AFE4066));
    canvas.drawPath(
      path,
      Paint()
        ..color = Color(0x99FE4066)
        ..style = PaintingStyle.stroke
        ..strokeWidth = 1,
    );
  }

  @override
  bool shouldRepaint(_Path4Painter oldDelegate) => false;
}
